function drawScene() {
  const gamma = 1 / Math.sqrt(1 - currentV * currentV);
  const D = 80;
  const L = currentV * gamma * D; 
  const p = currentProgress; 

  if (currentFrame === 'Astronaut') {
    dynamicElements.boxA.stroke({color: '#009999', width: 4}).fill('#f4fcfc');
    dynamicElements.boxB.stroke({color: '#ccc', width: 2, dasharray: '6,6'}).fill('none');
    panelA.opacity(1.0);
    panelB.opacity(0.35);
  } else {
    dynamicElements.boxA.stroke({color: '#b3d9d9', width: 3}).fill('#fff');
    dynamicElements.boxB.stroke({color: '#8844aa', width: 3, dasharray: 'none'}).fill('#faf4fc');
    panelA.opacity(0.35);
    panelB.opacity(1.0);
  }

  // Panel A Math
  dynamicElements.handA.transform({ rotate: p * 360, ox: 0, oy: 0 });
  const A_sx = 190, A_sy = 280;
  const A_mx = 200, A_my = 200;
  const A_rx = 210, A_ry = 280;

  if (p <= 0) {
    dynamicElements.pathA_up.hide();
    dynamicElements.pathA_down.hide();
    dynamicElements.pulseA.center(A_sx, A_sy);
  } else if (p <= 0.5) {
    const cx = A_sx + (A_mx - A_sx) * (p * 2);
    const cy = A_sy + (A_my - A_sy) * (p * 2);
    dynamicElements.pathA_up.show().plot(A_sx, A_sy, cx, cy);
    dynamicElements.pathA_down.hide();
    dynamicElements.pulseA.center(cx, cy);
  } else {
    dynamicElements.pathA_up.show().plot(A_sx, A_sy, A_mx, A_my);
    const p2 = (p - 0.5) * 2;
    const cx = A_mx + (A_rx - A_mx) * p2;
    const cy = A_my + (A_ry - A_my) * p2;
    if(p2 > 0.001) dynamicElements.pathA_down.show().plot(A_mx, A_my, cx, cy);
    else dynamicElements.pathA_down.hide();
    dynamicElements.pulseA.center(cx, cy);
  }

  // Panel B Math
  dynamicElements.handB.transform({ rotate: p * gamma * 360, ox: 0, oy: 0 });
  const cx2 = 530; 
  const cx1 = cx2 - L;
  const cx3 = cx2 + L;

  dynamicElements.cabin1.center(cx1, 240);
  dynamicElements.cabin2.center(cx2, 240);
  dynamicElements.cabin3.center(cx3, 240);

  const B_sy = 280, B_my = 200, B_ry = 280;
  const B_sx = cx1 - 10;
  const B_mx = cx2;
  const B_rx = cx3 + 10;

  if (p <= 0) {
    dynamicElements.pathB_up.hide();
    dynamicElements.pathB_down.hide();
    dynamicElements.pulseB.center(B_sx, B_sy);
  } else if (p <= 0.5) {
    const cx = B_sx + (B_mx - B_sx) * (p * 2);
    const cy = B_sy + (B_my - B_sy) * (p * 2);
    dynamicElements.pathB_up.show().plot(B_sx, B_sy, cx, cy);
    dynamicElements.pathB_down.hide();
    dynamicElements.pulseB.center(cx, cy);
  } else {
    dynamicElements.pathB_up.show().plot(B_sx, B_sy, B_mx, B_my);
    const p2 = (p - 0.5) * 2;
    const cx = B_mx + (B_rx - B_mx) * p2;
    const cy = B_my + (B_ry - B_my) * p2;
    if(p2 > 0.001) dynamicElements.pathB_down.show().plot(B_mx, B_my, cx, cy);
    else dynamicElements.pathB_down.hide();
    dynamicElements.pulseB.center(cx, cy);
  }

  const brY = 320;
  dynamicElements.bracketL1_B.plot(`M ${cx1} ${brY-5} L ${cx1} ${brY} L ${cx2} ${brY} L ${cx2} ${brY-5}`);
  dynamicElements.bracketL2_B.plot(`M ${cx2} ${brY-5} L ${cx2} ${brY} L ${cx3} ${brY} L ${cx3} ${brY-5}`);
  dynamicElements.labelL1_B.center((cx1+cx2)/2, brY + 10);
  dynamicElements.labelL2_B.center((cx2+cx3)/2, brY + 10);
  dynamicElements.labelBeginB.center(cx1, 355);
  dynamicElements.labelEndB.center(cx3, 355);

  // Panel C Math
  const C_cx = 400;
  const C_my = 430;
  const C_sy = 510;

  dynamicElements.tri.plot([[C_cx, C_my], [C_cx - L, C_sy], [C_cx + L, C_sy]]);
  dynamicElements.alt.plot(C_cx, C_my, C_cx, C_sy);

  dynamicElements.labelL1_C.center(C_cx - L/2, C_sy + 12);
  dynamicElements.labelL2_C.center(C_cx + L/2, C_sy + 12);
  dynamicElements.labelS1_C.center(C_cx - L/2 - 15, (C_my + C_sy)/2 - 12);
  dynamicElements.labelS2_C.center(C_cx + L/2 + 15, (C_my + C_sy)/2 - 12);

  if (p <= 0) {
    dynamicElements.pathC_up.hide();
    dynamicElements.pathC_down.hide();
    dynamicElements.pulseC.center(C_cx - L, C_sy);
  } else if (p <= 0.5) {
    const cx = (C_cx - L) + L * (p * 2);
    const cy = C_sy + (C_my - C_sy) * (p * 2);
    dynamicElements.pathC_up.show().plot(C_cx - L, C_sy, cx, cy);
    dynamicElements.pathC_down.hide();
    dynamicElements.pulseC.center(cx, cy);
  } else {
    dynamicElements.pathC_up.show().plot(C_cx - L, C_sy, C_cx, C_my);
    const p2 = (p - 0.5) * 2;
    const cx = C_cx + L * p2;
    const cy = C_my + (C_sy - C_my) * p2;
    if(p2 > 0.001) dynamicElements.pathC_down.show().plot(C_cx, C_my, cx, cy);
    else dynamicElements.pathC_down.hide();
    dynamicElements.pulseC.center(cx, cy);
  }
}

function update_shuttleVelocity(val) {
  currentV = val;
  document.getElementById('shuttleVelocityVal').textContent = val.toFixed(2);
  drawScene();
}

function toggle_observerFrame(isEarth) {
  currentFrame = isEarth ? 'Earth' : 'Astronaut';
  drawScene();
}

function setEvent(evt) {
  if(evt === 'Emission') currentProgress = 0;
  else if(evt === 'Reflection') currentProgress = 0.5;
  else if(evt === 'Reception') currentProgress = 1.0;
  document.getElementById('eventSequenceInput').value = currentProgress;
  updateEventButtons(evt);
  drawScene();
}

function updateEventProgress(val) {
  currentProgress = parseFloat(val);
  let stateStr = '';
  if(currentProgress === 0) stateStr = 'Emission';
  else if(currentProgress === 0.5) stateStr = 'Reflection';
  else if(currentProgress === 1.0) stateStr = 'Reception';
  updateEventButtons(stateStr);
  drawScene();
}

function updateEventButtons(activeId) {
  ['Emission','Reflection','Reception'].forEach(e => {
    const btn = document.getElementById('btn_' + e);
    if(btn) btn.className = (e === activeId) ? 'active' : '';
  });
}

function setStep(idx) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, idx));
  const step = demoSteps[currentStep];

  document.getElementById('demoNarration').innerHTML = `<strong>${step.title}</strong><br/>${step.narration}`;
  document.getElementById('stepLabel').innerText = `Step ${currentStep + 1} / ${demoSteps.length}`;
  document.getElementById('btnPrev').disabled = (currentStep === 0);
  document.getElementById('btnNext').disabled = (currentStep === demoSteps.length - 1);

  if (step.state.observerFrame) {
    const isEarth = (step.state.observerFrame === 'Earth');
    document.getElementById('frameEarth').checked = isEarth;
    document.getElementById('frameAstro').checked = !isEarth;
    toggle_observerFrame(isEarth);
  }
  if (step.state.shuttleVelocity !== undefined) {
    document.getElementById('shuttleVelocityInput').value = step.state.shuttleVelocity;
    update_shuttleVelocity(step.state.shuttleVelocity);
  }
  if (step.state.eventSequence) {
    setEvent(step.state.eventSequence);
  }
}

window.nextStep = function() { setStep(currentStep + 1); };
window.prevStep = function() { setStep(currentStep - 1); };

initScene();
setTimeout(() => {
  setStep(0);
  window.__markRendered();
}, 50);
