var labelR2 = txt('R₂', 337, 155, 37, 'middle');

// [elided] addInteractivity(el, title, body, tip) — wires showTooltip/hideTooltip/showPopup, then is called on regionLeft, regionRight, regionType2, sliceL, sliceR, sliceH
var state = {
  typeII: false,
  f1: '-x + 1',
  f2: 'x + 1',
  geom: { xL: -2, xA: 0, xR: 2, yA: 1 }
};

function compileExpr(s) {
  var expr = String(s || '').replace(/\s+/g, '').replace(/\^/g, '**');
  expr = expr.replace(/(^|[\+\-\*\/\(])x/g, '// @FIGURE_CODE_BEGIN1*x');
  expr = expr.replace(/([0-9.])x/g, '// @FIGURE_CODE_BEGIN*x');
  if (!/^[0-9xX+\-*/().\s*]+$/.test(expr)) throw new Error('Only arithmetic expressions in x are supported.');
  return new Function('x', 'return Number(' + expr.replace(/X/g, 'x') + ');');
}
// [elided] rootBetween(fn, a, b) — bisection;  findRoot(fn, a, b, prefer) — scans 160 samples for the sign change nearest `prefer`
function evaluateGeometry() {
  try {
    var f1 = compileExpr(state.f1), f2 = compileExpr(state.f2);
    var xA = findRoot(function (x) { return f1(x) - f2(x); }, -3.5, 3.5, 0);
    if (xA === null) throw new Error('No intersection');
    var yA = f1(xA);
    var xL = findRoot(function (x) { return f1(x) - 3; }, -3.5, Math.min(xA, 3.5), -2);
    var xR = findRoot(function (x) { return f2(x) - 3; }, Math.max(xA, -3.5), 3.5, 2);
    if (xL === null || xR === null || !isFinite(yA)) throw new Error('Bad boundary');
    if (xL > xR) { var t = xL; xL = xR; xR = t; }
    state.geom = { xL: xL, xA: xA, xR: xR, yA: yA, f1: f1, f2: f2 };
  } catch (e) {
    state.geom = {
      xL: -2, xA: 0, xR: 2, yA: 1,
      f1: function (x) { return -x + 1; },
      f2: function (x) { return x + 1; }
    };
  }
}
// [elided] polyStr(points) — maps world points to an SVG points string
function updateIntegralText() {
  var g = state.geom;
  var el = document.getElementById('integralText');
  if (!el) return;
  if (state.typeII) {
    el.textContent = 'Type II: ∫ᵧ₌' + fmt(g.yA) + '³ ∫ₓ₌left(y)ʳⁱᵍʰᵗ⁽ʸ⁾ dA';
  } else {
    el.textContent = 'Type I: ∫' + fmt(g.xL) + '→' + fmt(g.xA) + '∫f₁(x)→3 dA + ∫' + fmt(g.xA) + '→' + fmt(g.xR) + '∫f₂(x)→3 dA';
  }
}
function redraw() {
  evaluateGeometry();
  var g = state.geom;
  var xL = g.xL, xA = g.xA, xR = g.xR, yA = g.yA;
  regionLeft.plot(polyStr([[xL, 3], [xA, yA], [xA, 3]]));
  regionRight.plot(polyStr([[xA, 3], [xA, yA], [xR, 3]]));
  regionType2.plot(polyStr([[xL, 3], [xA, yA], [xR, 3]]));
  topLine.plot(X(xL), Y(3), X(xR), Y(3));
  leftLine.plot(X(xL), Y(3), X(xA), Y(yA));
  rightLine.plot(X(xA), Y(yA), X(xR), Y(3));

  var xlSlice = (xL + xA) / 2;
  var xrSlice = (xA + xR) / 2;
  sliceL.plot(X(xlSlice), Y(3), X(xlSlice), Y(g.f1(xlSlice)));
  sliceR.plot(X(xrSlice), Y(3), X(xrSlice), Y(g.f2(xrSlice)));

  var yh = (3 + yA) / 2;
  var xhL = xL + (xA - xL) * ((3 - yh) / (3 - yA));
  var xhR = xR + (xA - xR) * ((3 - yh) / (3 - yA));
  sliceH.plot(X(xhL), Y(yh), X(xhR), Y(yh));

  regionLeft.animate(160).opacity(state.typeII ? 0 : 0.95);
  regionRight.animate(160).opacity(state.typeII ? 0 : 0.95);
  regionType2.animate(160).opacity(state.typeII ? 0.9 : 0);
  sliceL.animate(160).opacity(state.typeII ? 0 : 1);
  sliceR.animate(160).opacity(state.typeII ? 0 : 1);
  sliceH.animate(160).opacity(state.typeII ? 1 : 0);

  labelR1.animate(160).opacity(state.typeII ? 0 : 1);
  labelR2.animate(160).opacity(state.typeII ? 0 : 1);
  labelLeftEq.text('y = ' + state.f1.replace(/-/g, '−'));
  labelRightEq.text('y = ' + state.f2.replace(/-/g, '−'));
  updateIntegralText();
}
function toggle_integrationType(on) {
  state.typeII = !!on;
  redraw();
}
function updateBoundaryEquations() {
  state.f1 = document.getElementById('f1Input').value || '-x + 1';
  state.f2 = document.getElementById('f2Input').value || 'x + 1';
  redraw();
}

var demoSteps = [
  {
    narration: 'Integrating with vertical slices (Type I) requires splitting the triangle into sub-regions R1 and R2 at x = 0, because the lower boundary formula abruptly changes from y = -x + 1 to y = x + 1.',
    typeII: false
  },
  {
    narration: 'Try editing the equations for the left and right boundaries. Observe how the shape of the regions and the corresponding integration limits automatically update.',
    typeII: false
  },
  {
    narration: 'Switching to horizontal slices (Type II) allows a single continuous sweep across the whole region, consolidating the problem into one double integral.',
    typeII: true
  }
];
var currentStep = 0;
function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var s = demoSteps[currentStep];
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  var chk = document.getElementById('integrationTypeInput');
  if (narr) narr.textContent = s.narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length;
  if (chk) chk.checked = s.typeII;
  toggle_integrationType(s.typeII);
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

window.toggle_integrationType = toggle_integrationType;
window.updateBoundaryEquations = updateBoundaryEquations;
window.prevStep = prevStep;
window.nextStep = nextStep;

redraw();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

