const W = 800;
const H = 560;
const draw = window.SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, W, H);

let panelA = draw.group();
let panelB = draw.group();
let pC = draw.group();
let dynamicElements = {};

let currentV = 0.5;
let currentFrame = 'Astronaut';
let currentProgress = 1.0;
let currentStep = 0;

const demoSteps = [
  {
    title: "The Astronaut's Frame",
    narration: "To the astronaut moving with the clock, the light pulse simply travels straight up to the mirror and straight back down. The total distance is 2D.",
    state: { observerFrame: "Astronaut", shuttleVelocity: 0.5, eventSequence: "Reception" }
  },
  {
    title: "The Earth Observer's Frame",
    narration: "To an observer on Earth, the shuttle moves forward while the light is in transit. The light must take a diagonal path to catch the moving mirror and receiver.",
    state: { observerFrame: "Earth", shuttleVelocity: 0.5, eventSequence: "Reception" }
  },
  {
    title: "Higher Speed, Longer Path",
    narration: "Increase the shuttle's speed. The diagonal path 's' becomes much longer. Since the speed of light is constant, a longer path requires more time, forcing the Earth clock to tick more than the astronaut's clock.",
    state: { observerFrame: "Earth", shuttleVelocity: 0.9, eventSequence: "Reception" }
  },
  {
    title: "Shared Events",
    narration: "Step back to the reflection event. Both observers agree this physical moment happens, but the geometry of the triangle shows that the Earth observer measures a longer path length to reach it.",
    state: { observerFrame: "Earth", shuttleVelocity: 0.9, eventSequence: "Reflection" }
  }
];

function drawCabin(parent) {
  const g = parent.group();
  g.rect(60, 110).center(0, 0).fill('#f8f9fa').stroke({width: 2, color: '#aaa', dasharray: '6,4', rx: 8});
  g.rect(24, 4).center(0, -40).fill('#ddd').stroke('#666'); // Mirror
  g.rect(10, 10).center(-10, 40).fill('#ffcc00').stroke('#333'); // Source
  g.rect(12, 10).center(10, 40).fill('#999').stroke('#333'); // Receiver
  return g;
}

function createStackedFraction(parent, fontSize) {
  const g = parent.group();
  const fStyle = {size: fontSize, style: 'italic'}; 
  g.text('L =').font(fStyle).move(-24, -fontSize/2 - 4);
  g.text('v\u0394t').font(fStyle).move(5, -fontSize - 2);
  g.line(2, 0, 26, 0).stroke({width: 1, color: '#000'}); 
  g.text('2').font({size: fontSize}).move(10, 2);
  return g;
}

function initScene() {
  // Context Shuttle at top
  const shuttle = draw.group().move(100, 15);
