  shuttle.rect(16, 22).center(12, 45).fill('#444');
  shuttle.polygon('210,38 230,44 230,50 210,50').fill('#8ce');

  const beamGroup = draw.group();
  beamGroup.polygon('180,95 260,95 280,140 20,140').fill('#e6f4f4').opacity(0.8);
  beamGroup.line(180, 95, 20, 140).stroke({width: 1.5, color: '#b3d9d9'});
  beamGroup.line(260, 95, 280, 140).stroke({width: 1.5, color: '#b3d9d9'});
  beamGroup.back();

  // Panel A
  dynamicElements.boxA = panelA.rect(260, 255).move(20, 140).fill('#fff').stroke({width: 3, color: '#b3d9d9', rx: 12});
  dynamicElements.boxA.back();
  panelA.text('(a)').move(150, 375).font({size: 15, anchor: 'middle', weight: 'bold'});

  const astro = panelA.group().move(80, 250);
