  astro.circle(26).center(0, -26).fill('none').stroke({width:2, color:'#aaa'});
  astro.path('M -12 -5 L -22 5 M 12 -5 L 22 5').stroke({width: 6, color: '#e66a22', linecap: 'round'});
  astro.path('M -6 17 L -10 35 M 6 17 L 10 35').stroke({width: 7, color: '#e66a22', linecap: 'round'});
  panelA.text('Astronaut').move(40, 225).font({size: 12, anchor: 'start'});

  dynamicElements.clockA = panelA.group().move(80, 335);
  dynamicElements.clockA.circle(30).center(0,0).fill('#fff').stroke({width: 2, color: '#333'});
  for(let i=0; i<8; i++) {
    let a = i * Math.PI / 4;
    dynamicElements.clockA.line(10*Math.cos(a), 10*Math.sin(a), 15*Math.cos(a), 15*Math.sin(a)).stroke({width:1, color:'#666'});
  }
  dynamicElements.handA = dynamicElements.clockA.line(0,0, 0,-12).stroke({width: 2, color: '#d00', linecap: 'round'});
  dynamicElements.clockA.text('\u0394\u03C4').center(0, 23).font({size: 14, style: 'italic'});
  dynamicElements.clockA.css('cursor','pointer').on('mousemove', e => showTooltip('Proper time (Δτ): Time measured by the observer moving with the clock.', e)).on('mouseleave', hideTooltip);

  panelA.rect(10, 10).center(190, 280).fill('#ffcc00').stroke('#333');
  panelA.rect(12, 10).center(210, 280).fill('#999').stroke('#333');
  panelA.rect(30, 4).center(200, 200).fill('#ddd').stroke('#666');
  panelA.text('Light\nsource').move(170, 290).font({size: 11, anchor: 'end'}).leading(1.1);
  panelA.text('Receiver').move(220, 290).font({size: 11, anchor: 'start'});
  panelA.text('Mirror').move(200, 180).font({size: 12, anchor: 'middle'});
  panelA.path('M 235 200 L 240 200 M 240 200 L 240 280 M 235 280 L 240 280').stroke({width:1, color:'#333'}).fill('none');
  panelA.text('D').move(248, 230).font({size: 13, style: 'italic', anchor: 'start'});

  const markerTeal = draw.marker(8, 8, function(add) { add.polygon('0,0 8,4 0,8').fill('#009999'); }).ref(8, 4);
  dynamicElements.pathA_up = panelA.line().stroke({width: 2, color: '#009999'}).marker('end', markerTeal);
  dynamicElements.pathA_down = panelA.line().stroke({width: 2, color: '#009999'}).marker('end', markerTeal);
  dynamicElements.pulseA = panelA.circle(10).fill('yellow').stroke('#e6b800');

  // Panel B
  dynamicElements.boxB = panelB.rect(480, 255).move(290, 140).fill('none').stroke({width: 2, color: '#ccc', dasharray: '6,6', rx: 12});
  dynamicElements.boxB.back();
  panelB.text('(b)').move(530, 375).font({size: 15, anchor: 'middle', weight: 'bold'});

  panelB.polygon('300,355 770,355 730,395 260,395').fill('#e6dfd3');

  const observer = panelB.group().move(530, 350);
  observer.circle(14).center(0, -20).fill('#eec5a8');
  observer.rect(18, 24).center(0, 0).fill('#7b9b5f').radius(3);
  observer.path('M -4 12 L -6 28 M 4 12 L 6 28').stroke({width: 6, color: '#576c8c', linecap: 'round'});
  observer.path('M -9 -5 L -14 10 M 9 -5 L 14 10').stroke({width: 4, color: '#7b9b5f', linecap: 'round'});
  panelB.text('Observer\non Earth').move(510, 355).font({size: 11, anchor: 'end'}).leading(1.1);

  dynamicElements.clockB = panelB.group().move(590, 345);
  dynamicElements.clockB.circle(30).center(0,0).fill('#fff').stroke({width: 2, color: '#333'});
  for(let i=0; i<8; i++) {
    let a = i * Math.PI / 4;
    dynamicElements.clockB.line(10*Math.cos(a), 10*Math.sin(a), 15*Math.cos(a), 15*Math.sin(a)).stroke({width:1, color:'#666'});
  }
  dynamicElements.handB = dynamicElements.clockB.line(0,0, 0,-12).stroke({width: 2, color: '#d00', linecap: 'round'});
  dynamicElements.clockB.text('\u0394t').center(0, 23).font({size: 14, style: 'italic'});
  dynamicElements.clockB.css('cursor','pointer').on('mousemove', e => showTooltip('Dilated time (Δt): Earth observer measures more time because the light must travel a longer diagonal path.', e)).on('mouseleave', hideTooltip);

  dynamicElements.cabin1 = drawCabin(panelB);
  dynamicElements.cabin2 = drawCabin(panelB);
  dynamicElements.cabin3 = drawCabin(panelB);

  const markerPurple = draw.marker(8, 8, function(add) { add.polygon('0,0 8,4 0,8').fill('#8844aa'); }).ref(8, 4);
  dynamicElements.pathB_up = panelB.line().stroke({width: 2, color: '#8844aa'}).marker('end', markerPurple);
  dynamicElements.pathB_down = panelB.line().stroke({width: 2, color: '#8844aa'}).marker('end', markerPurple);
  dynamicElements.pulseB = panelB.circle(10).fill('yellow').stroke('#e6b800');

  dynamicElements.bracketL1_B = panelB.path().fill('none').stroke('#333');
